CAT = "cnorAssess"; SEG = "ASM"
# Subject Area 1: Pre/postoperative Patient Assessment and Diagnosis (CCI CNOR Task & Knowledge
# Statements, updated 12/2023; 15% of the scored exam). Sources in sources.md.
Q = [
("How many patient identifiers are used to confirm identity before surgery?",
 "Two", ["One", "Three", "Four"],
 "Two identifiers, such as full name and date of birth, are checked against the wristband and records. A room number is never one of them."),
("Both identifiers match, but the patient's allergy band is missing. What next?",
 "Confirm allergies, apply band", ["Proceed, allergies were asked", "Wait until the PACU", "Let the surgeon decide later"],
 "Allergy information is checked against the record and the patient, and the band is applied before the patient goes into the room."),
("During surgical consent, which part is the nurse's role?",
 "Witnessing the signature", ["Explaining surgical risks", "Choosing the procedure", "Describing the alternatives"],
 "The surgeon explains the procedure, risks and alternatives; the nurse may witness the signature and checks that the form is complete."),
("The consent says left knee arthroscopy, and the schedule says right. What happens next?",
 "Hold until the conflict is resolved", ["Proceed with the scheduled right side", "Proceed with the consent's left side", "Ask the patient to choose a side"],
 "Any mismatch between consent, schedule and history stops the process until the surgeon resolves it with the patient and the records agree."),
("A patient took ginkgo biloba daily until yesterday. What surgical risk does this raise?",
 "Increased bleeding", ["Delayed emergence from anesthesia", "Low blood glucose during fasting", "Malignant hyperthermia crisis"],
 "Ginkgo inhibits platelet function, so it is reported to the surgeon and anesthesia provider during medication reconciliation."),
("Which home supplement is known to interact with many anesthetic and other drugs by inducing liver enzymes?",
 "St John's wort", ["Coenzyme Q10 tablets", "Omega-3 fish oil", "Vitamin D3 drops"],
 "St John's wort induces cytochrome P450 enzymes, lowering levels of many drugs, so it belongs on the medication list."),
("A patient with a latex allergy reports reactions to bananas and kiwi. Why is this relevant?",
 "Cross-reactive food allergy", ["Unrelated seasonal allergy", "Food intolerance, not allergy", "Marker of iodine allergy"],
 "Latex-fruit syndrome links latex allergy with bananas, avocado, kiwi and chestnut, so a reaction to these foods supports a latex history."),
("Which patient has the highest risk of latex allergy?",
 "Child with spina bifida", ["Adult with asthma history", "Child with tonsillitis", "Adult having first surgery"],
 "Repeated early exposure to latex through surgery and catheterization gives patients with spina bifida a high rate of latex sensitization."),
("Which pain scale suits a 3-year-old who cannot rate pain in numbers?",
 "FLACC scale", ["0 to 10 numeric scale", "Visual analog line", "Aldrete score"],
 "FLACC scores face, legs, activity, cry and consolability, so it works for children who cannot self-report."),
("What does the Aldrete score assess?",
 "Readiness to leave PACU", ["Risk of pressure injury", "Ease of intubation", "Fall risk on the ward"],
 "The Aldrete score rates activity, respiration, circulation, consciousness and oxygen saturation to judge recovery after anesthesia."),
("Which item is part of the modified Aldrete score?",
 "Oxygen saturation", ["Urine output per hour", "Pain rating", "Capillary glucose"],
 "The modified score replaced skin color with oxygen saturation, alongside activity, respiration, circulation and consciousness."),
("Before a carotid endarterectomy, which baseline is most important to record?",
 "Neurological status", ["Bowel sounds", "Visual acuity chart", "Skin turgor and hydration"],
 "A baseline neurological check lets the team recognize a new deficit, such as weakness or speech change, after carotid surgery."),
("Before a femoral-popliteal bypass, what baseline assessment is recorded?",
 "Distal pulses", ["Hand grip strength", "Pupil size and reaction", "Abdominal girth"],
 "Pedal and popliteal pulses before vascular surgery give the reference for judging limb perfusion afterwards."),
("Why is metal body jewelry removed before surgery with electrosurgery?",
 "It can cause a burn", ["It interferes with imaging only", "It raises infection rates", "It blocks the pulse oximeter"],
 "Metal can provide an alternate path for current, creating a burn at the jewelry site, and it can catch on drapes or cause pressure injury."),
("A patient has a cardiac implantable device. What is confirmed before surgery?",
 "Device type and plan", ["Battery brand only", "Date of implant only", "Patient's preferred arm"],
 "The team needs to know whether it is a pacemaker or defibrillator and what the plan is for it during electrosurgery."),
("Why should a patient's child not interpret preoperative teaching?",
 "Errors and loss of privacy", ["It takes too much time", "Children speak too fast", "Children cannot read forms"],
 "Family interpreters, especially children, may omit or change medical meaning and expose private details; a qualified interpreter is used."),
("A patient nods after fasting teaching but cannot say when to stop eating. What does this show?",
 "Teaching not yet understood", ["Teaching is complete", "Patient is noncompliant", "Patient needs sedation"],
 "Being able to state the instructions in their own words is the evidence of understanding; a nod is not, so the teaching is repeated another way."),
("A preoperative potassium is 6.3 mEq/L. What should the nurse do?",
 "Report it before surgery", ["Recheck it after surgery", "Note it in the chart only", "Give oral fluids"],
 "Hyperkalemia can cause dysrhythmias under anesthesia, so a critical value is reported to the surgeon and anesthesia provider before the case."),
("Why does a patient with heavy daily alcohol use need attention before surgery?",
 "Risk of withdrawal", ["Faster wound healing", "Lower anesthetic needs", "No added risk"],
 "Withdrawal can begin within days of stopping, and chronic use can change anesthetic needs and raise bleeding risk."),
("Which Braden subscale reflects a patient's usual food intake?",
 "Nutrition", ["Moisture", "Activity", "Friction and shear"],
 "The Braden scale rates sensory perception, moisture, activity, mobility, nutrition and friction or shear; poor intake lowers the nutrition score and raises risk."),
("Which finding raises a patient's risk of perioperative pressure injury most?",
 "Low albumin, little padding", ["Brief local anesthetic case", "Normal BMI and active", "Same-day discharge plan"],
 "Poor nutrition and little padding over bony prominences raise pressure injury risk, especially in long cases."),
("Which nursing diagnosis fits a patient who fears the operation and asks repeated questions?",
 "Anxiety", ["Impaired gas exchange", "Risk for bleeding", "Hypothermia"],
 "Repeated questions and stated fear point to anxiety, which is addressed with information and reassurance."),
("What does the Perioperative Nursing Data Set (PNDS) provide?",
 "Standard perioperative terms", ["Weight-based drug dosing tables", "Billing codes for surgeons", "Instrument tray contents"],
 "PNDS is a standardized vocabulary of perioperative nursing diagnoses, interventions and outcomes."),
("A toddler cries when separated from a parent before surgery. What is expected at this age?",
 "Separation anxiety", ["Fear of body mutilation", "Concern about privacy", "Fear of losing control at work"],
 "Separation anxiety peaks in toddlers, so keeping the parent close as long as policy allows helps."),
("An older adult cannot hear questions clearly in the holding area. What helps most?",
 "Hearing aids in until induction", ["Speak at a higher pitch", "Ask the questions in writing later", "Ask the family to answer instead"],
 "Leaving hearing aids in place until the patient is asleep supports communication and consent checks; they are labeled and kept safe."),
("A patient's DNR order is in the chart. What happens before surgery?",
 "Discuss and document the plan", ["Suspend it automatically in the OR", "Cancel the procedure", "Keep it fully in force unchanged"],
 "DNR status is not automatically suspended; the patient and team discuss what applies during anesthesia and surgery and record the decision."),
("A warfarin patient's INR is high on the morning of elective surgery. What is done?",
 "Report it before the case", ["Proceed as scheduled", "Give vitamin K on your own", "Recheck it after surgery"],
 "An elevated INR raises bleeding risk, so it is reported to the surgeon and anesthesia provider, who decide whether to delay or reverse."),
("A patient with diabetes is NPO before surgery. What is monitored?",
 "Blood glucose", ["Serum calcium level", "Urine specific gravity", "Liver enzyme panel"],
 "Fasting and stress change glucose, and the CDC surgical site infection guideline targets perioperative glucose below 200 mg/dL."),
]
